public class OrderEventPublisher {
    private final SnsClient snsClient;
    private final String orderTopicArn;

    public OrderEventPublisher(SnsClient snsClient, String orderTopicArn) {
        this.snsClient = snsClient;
        this.orderTopicArn = orderTopicArn;
    }

    public void publishOrderCreated(OrderDto order) {
        PublishRequest request = PublishRequest.builder()
            .topicArn(orderTopicArn)
            .message(order.toJson())
            .messageAttributes(Map.of(
                "EventType", MessageAttributeValue.builder()
                    .dataType("String")
                    .stringData("OrderCreated")
                    .build()
            ))
            .build();

        snsClient.publish(request);
    }
}
